import { Component, h, Host, Element, Prop } from '@stencil/core';

/**
 * @slot default - Renders the scrollable content inside the native scrollbar container.
 */
@Component({
  tag: 'ks-scrollbar',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsScrollbar {
  @Element() el!: HTMLKsScrollbarElement;

  /** Specifies if the scrollbar should use the thin [scrollbar-width](https://developer.mozilla.org/en-US/docs/Web/CSS/scrollbar-width) to save space. */
  @Prop() thin = false;

  render() {
    return (
      <Host class="KsScrollbar" ks-thin={this.thin}>
        <slot></slot>
      </Host>
    );
  }
}
